import 'dart:convert';
import 'dart:io';

class UserServiceConfig {
  final String? apiKey;
  final String? baseUrl;

  UserServiceConfig({this.apiKey, this.baseUrl});

  factory UserServiceConfig.fromJson(Map<String, dynamic> json) {
    return UserServiceConfig(
      apiKey: json['apiKey'] as String?,
      baseUrl: json['baseUrl'] as String?,
    );
  }

  /// Carga la configuración desde un archivo JSON en [path]. Lanzará excepciones
  /// si el archivo no existe o el JSON es inválido.
  static Future<UserServiceConfig> fromFile(String path) async {
    final file = File(path);
    if (!await file.exists()) {
      throw Exception('Config file not found: $path');
    }
    final contents = await file.readAsString();
    final Map<String, dynamic> json =
        jsonDecode(contents) as Map<String, dynamic>;
    return UserServiceConfig.fromJson(json);
  }
}
